%[metadata:view]
%   data: {"layout":"inline","rightPanelPercent":40}
%---
%[output:7027c976]
%   data: {"dataType":"text","outputData":{"text":"The current folder is now \/Users\/ernesto\/MATLAB-Drive\/MtMresources\/data\/unit2\n","truncated":false}}
